// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CalendarIcon, CheckIcon, GlobeIcon, LinkIcon, PlusIcon, RepeatIcon } from 'lucide-react'
import type { ReactNode } from 'react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  LIST,
  PAGE,
  PRIORITY_RING,
  SAVED,
  TOKEN_BG,
  TONE_TEXT,
  TYPED,
  dueTone,
  formatDue,
  type Parsed,
} from './script'

const PANEL = 260
const PROJECT_DOT: Record<string, string> = {
  Work: 'bg-[#3b82f6]',
  Home: 'bg-[#10b981]',
  Team: 'bg-[#ec4899]',
}
const [INVOICE, PLANTS, BANK, DENTIST] = LIST
const TODAY = [PLANTS, BANK]
const BANK_INDEX = TODAY.indexOf(BANK)

/** The typed line cut at its tokens, so each recognised word can carry its highlight. */
const SEGMENTS = (() => {
  const parts: { text: string; kind?: Parsed['tokens'][number]['kind'] }[] = []
  let at = 0
  for (const token of TYPED.tokens) {
    if (token.start > at) parts.push({ text: TYPED.input.slice(at, token.start) })
    parts.push({ text: token.text, kind: token.kind })
    at = token.end
  }
  if (at < TYPED.input.length) parts.push({ text: TYPED.input.slice(at) })
  return parts
})()

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const view = (index: number) => {
    tl.to(qa('nav'), { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)', duration: 0.15 }, '<')
    tl.to(q(`nav-${index}`), { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)', duration: 0.15 }, '<')
  }
  const grow = (name: string, at?: string) =>
    tl.fromTo(
      q(name),
      { height: 0, opacity: 0 },
      { height: 'auto', opacity: 1, duration: 0.35, ease: 'power2.out', immediateRender: false },
      at,
    )

  step(0)
  move('composer', { at: 0.3, ax: 0.3 })
  click('composer')
  tl.to(q('placeholder'), { opacity: 0, duration: 0.1 }, '<')
  SEGMENTS.forEach((segment, index) => {
    tl.set(q(`seg-${index}`), { opacity: 1 })
    type(`seg-${index}`, segment.text, { speed: 0.04 })
  })
  tl.fromTo(
    qa('chip'),
    { opacity: 0, y: 4 },
    { opacity: 1, y: 0, duration: 0.25, stagger: 0.08, immediateRender: false },
    '+=0.1',
  )
  move('add', { at: '+=0.3' })
  click('add')
  tl.set(SEGMENTS.map((_, index) => q(`seg-${index}`)), { text: '' }, '+=0.05')
  tl.to(qa('chip'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('placeholder'), { opacity: 1, duration: 0.15 }, '<')
  grow('group-typed')

  step(1, '+=0.5')
  tl.fromTo(
    q('capture'),
    { opacity: 0, y: -8 },
    { opacity: 1, y: 0, duration: 0.35, ease: 'power3.out', immediateRender: false },
  )
  move('capture-add', { at: '+=0.3' })
  click('capture-add')
  tl.to(q('capture-idle'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('capture-done'), { opacity: 1, duration: 0.2 }, '<')
  grow('row-saved', '<0.1')
  tl.to(q('capture'), { opacity: 0, y: -8, duration: 0.3 }, '+=0.9')

  step(2, '+=0.3')
  move('nav-0')
  click('nav-0')
  view(0)
  tl.to(q('view-upcoming'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('view-today'), { opacity: 1, duration: 0.2 }, '<0.1')
  move(`check-${BANK_INDEX}`, { at: '+=0.2' })
  click(`check-${BANK_INDEX}`)
  tl.to(q(`check-${BANK_INDEX}`), { backgroundColor: '#60a5fa', borderColor: '#60a5fa', duration: 0.15 }, '<')
  tl.to(q(`tick-${BANK_INDEX}`), { opacity: 1, scale: 1, duration: 0.2, ease: 'back.out(3)' }, '<')
  tl.fromTo(
    q(`strike-${BANK_INDEX}`),
    { scaleX: 0 },
    { scaleX: 1, duration: 0.3, ease: 'power2.out', immediateRender: false },
    '<',
  )
  tl.to(q(`row-today-${BANK_INDEX}`), { opacity: 0.55, duration: 0.3 }, '<0.1')
  tl.set(q('progress-text'), { text: `1 of ${TODAY.length} done` }, '<')
  tl.to(q('progress-bar'), { scaleX: 1 / TODAY.length, duration: 0.4, ease: 'power2.out' }, '<')
  cursorOut('+=0.4')
  final()
  wait(1.4)

  tl.set([q('view-today'), q('capture'), q('capture-done'), ...qa('chip')], { opacity: 0 }, 0)
  tl.set([q('view-upcoming'), q('placeholder'), q('capture-idle')], { opacity: 1 }, 0)
  tl.set([q('group-typed'), q('row-saved')], { height: 0, opacity: 0 }, 0)
  tl.set(SEGMENTS.map((_, index) => q(`seg-${index}`)), { text: '', opacity: 0 }, 0)
  tl.set(q(`check-${BANK_INDEX}`), { backgroundColor: 'rgba(59,130,246,0.1)', borderColor: '#60a5fa' }, 0)
  tl.set(q(`tick-${BANK_INDEX}`), { opacity: 0, scale: 0.5 }, 0)
  tl.set(q(`strike-${BANK_INDEX}`), { scaleX: 0 }, 0)
  tl.set(q(`row-today-${BANK_INDEX}`), { opacity: 1 }, 0)
  tl.set(q('progress-text'), { text: `0 of ${TODAY.length} done` }, 0)
  tl.set(q('progress-bar'), { scaleX: 0 }, 0)
  tl.set(qa('nav'), { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)' }, 0)
  tl.set(q('nav-1'), { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)' }, 0)
}

function Row({ task, d, index, check }: { task: Parsed; d?: string; index?: number; check?: boolean }) {
  const tone = task.due == null ? null : dueTone(task.due, task.allDay)
  return (
    <div data-d={d} className="flex items-start gap-1.5 overflow-hidden py-[3px]">
      <span
        data-d={check ? `check-${index}` : undefined}
        className={`relative mt-px flex size-3 shrink-0 items-center justify-center rounded-full border ${PRIORITY_RING[task.priority]}`}
      >
        {check ? (
          <CheckIcon
            data-d={`tick-${index}`}
            className="size-2 text-canvas opacity-0"
            style={{ transform: 'scale(0.5)' }}
            strokeWidth={3.5}
          />
        ) : null}
      </span>
      <span className="min-w-0 flex-1">
        <span className="relative block truncate text-[9.5px] text-ink">
          {task.title}
          {check ? (
            <span
              data-d={`strike-${index}`}
              className="absolute inset-x-0 top-1/2 h-px origin-left bg-ink-soft"
              style={{ transform: 'scaleX(0)' }}
            />
          ) : null}
        </span>
        <span className="mt-px flex items-center gap-1.5 text-[7.5px]">
          {task.due != null && tone ? (
            <span className={`flex items-center gap-0.5 ${TONE_TEXT[tone]}`}>
              <CalendarIcon className="size-2" />
              {formatDue(task.due, task.allDay)}
              {task.recurrence !== 'none' ? <RepeatIcon className="size-2" /> : null}
            </span>
          ) : null}
          {'saved' in task ? <LinkIcon className="size-2 text-muted" /> : null}
          {task.labels.map((label) => (
            <span key={label} className="text-[#a78bfa]">
              @{label}
            </span>
          ))}
          {task.project ? (
            <span className="ml-auto flex items-center gap-1 text-muted">
              <span className={`size-1.5 rounded-full ${PROJECT_DOT[task.project]}`} />
              {task.project}
            </span>
          ) : (
            <span className="ml-auto flex items-center gap-1 text-muted">
              <span className="size-1.5 rounded-full bg-[var(--accent)]" />
              Inbox
            </span>
          )}
        </span>
      </span>
    </div>
  )
}

function Group({ label, tone, children }: { label: string; tone: string; children: ReactNode }) {
  return (
    <div className="border-b border-line/70 pb-1">
      <p className={`pt-1 text-[8px] font-semibold ${tone}`}>{label}</p>
      {children}
    </div>
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col" style={{ width: PANEL }}>
      <DockHeader />
      <div className="flex min-h-0 flex-1 flex-col gap-1.5 p-2">
        <div className="grid grid-cols-3 gap-0.5 rounded-md bg-ink/[0.04] p-0.5">
          {['Today', 'Upcoming', 'Inbox'].map((label, index) => (
            <span
              key={label}
              data-d={`nav nav-${index}`}
              className={`rounded py-1 text-center text-[9px] ${index === 1 ? 'bg-ink/10 text-ink' : 'text-muted'}`}
            >
              {label}
            </span>
          ))}
        </div>

        <div className="relative">
          <span
            data-d="composer"
            className="flex h-[26px] items-center gap-1 overflow-hidden rounded-md border border-line-strong bg-canvas/80 px-2 text-[9.5px] text-ink"
          >
            <PlusIcon className="size-3 shrink-0 text-muted" />
            <span className="relative min-w-0 flex-1 whitespace-nowrap">
              <span data-d="placeholder" className="absolute left-0 text-muted">
                e.g. Read this tomorrow 5pm p2 #Work @reading
              </span>
              {SEGMENTS.map((segment, index) => (
                <span
                  key={index}
                  data-d={`seg-${index}`}
                  className={segment.kind ? `rounded-sm opacity-0 ${TOKEN_BG[segment.kind]}` : 'opacity-0'}
                />
              ))}
            </span>
            <span
              data-d="add"
              className="shrink-0 rounded bg-[var(--accent)] px-1.5 py-0.5 text-[8px] font-medium text-canvas"
            >
              Add
            </span>
          </span>
          <span className="mt-1 flex h-3.5 items-center gap-1 text-[7.5px]">
            <span data-d="chip" className={`flex items-center gap-0.5 rounded bg-ink/[0.05] px-1 py-px opacity-0 ${TONE_TEXT[dueTone(TYPED.due!, TYPED.allDay)]}`}>
              <CalendarIcon className="size-2" />
              {formatDue(TYPED.due!, TYPED.allDay)}
            </span>
            <span data-d="chip" className="flex items-center gap-1 rounded bg-ink/[0.05] px-1 py-px text-ink-soft opacity-0">
              <span className={`size-1.5 rounded-full ${PROJECT_DOT[TYPED.project!]}`} />
              {TYPED.project}
            </span>
            <span data-d="chip" className="rounded bg-ink/[0.05] px-1 py-px text-[#fb923c] opacity-0">
              P{TYPED.priority}
            </span>
          </span>
        </div>

        <div className="relative min-h-0 flex-1">
          <div data-d="view-upcoming" className="absolute inset-0 overflow-hidden">
            <Group label="Today" tone={TONE_TEXT.today}>
              <Row task={PLANTS} />
              <Row task={BANK} />
            </Group>
            <Group label="Tomorrow" tone={TONE_TEXT.tomorrow}>
              <Row task={SAVED} d="row-saved" />
              <Row task={INVOICE} />
            </Group>
            <Group label={formatDue(DENTIST.due!, true)} tone={TONE_TEXT.week}>
              <Row task={DENTIST} />
            </Group>
            <div data-d="group-typed" className="overflow-hidden">
              <Group label={formatDue(TYPED.due!, true)} tone="text-ink-soft">
                <Row task={TYPED} />
              </Group>
            </div>
          </div>

          <div data-d="view-today" className="absolute inset-0 opacity-0">
            <div className="flex items-center gap-2 pb-1 text-[8px] text-muted">
              <span data-d="progress-text">0 of {TODAY.length} done</span>
              <span className="h-1 flex-1 overflow-hidden rounded-full bg-ink/[0.08]">
                <span
                  data-d="progress-bar"
                  className="block h-full origin-left rounded-full bg-[var(--accent)]"
                  style={{ transform: 'scaleX(0)' }}
                />
              </span>
            </div>
            {TODAY.map((task, index) => (
              <div key={task.title} data-d={`row-today-${index}`}>
                <Row task={task} index={index} check={index === BANK_INDEX} />
              </div>
            ))}
          </div>

          <div
            data-d="capture"
            className="absolute inset-x-0 top-0 rounded-lg border border-line-strong bg-elevated p-2 opacity-0 shadow-2xl"
          >
            <p className="text-[7.5px] font-medium uppercase tracking-[0.14em] text-muted">
              Current page
            </p>
            <p className="mt-1 flex items-center gap-1.5 text-[9.5px] text-ink">
              <GlobeIcon className="size-3 shrink-0 text-muted" />
              <span className="truncate">{PAGE.title}</span>
            </p>
            <div className="relative mt-1.5 h-[18px]">
              <span data-d="capture-idle" className="absolute inset-0 flex items-center gap-1">
                <span
                  data-d="capture-add"
                  className="rounded bg-[var(--accent)] px-1.5 py-0.5 text-[8px] font-medium text-canvas"
                >
                  Add for tomorrow
                </span>
                <span className="rounded border border-line-strong px-1.5 py-0.5 text-[8px] text-ink-soft">
                  Pick a date
                </span>
              </span>
              <span
                data-d="capture-done"
                className="absolute inset-0 flex items-center gap-1 text-[8.5px] text-[#34d399] opacity-0"
              >
                <CheckIcon className="size-3" /> Saved for {formatDue(SAVED.due!, SAVED.allDay)}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function Page() {
  return (
    <div className="h-full bg-[#fafafa] px-4 pt-3 text-[#111]">
      <p className="text-[8px] font-semibold uppercase tracking-[0.2em] text-[#2563eb]">
        Northwind Blog
      </p>
      <h3 className="mt-1 text-[15px] font-bold leading-tight tracking-tight">{PAGE.title}</h3>
      <p className="mt-1 text-[8px] text-[#64748b]">12 min read</p>
      <div className="mt-3 space-y-1.5">
        {[94, 88, 97, 72, 90, 84, 60, 92, 78, 86, 66].map((width, index) => (
          <span
            key={index}
            className="block h-1.5 rounded-full bg-black/[0.08]"
            style={{ width: `${width}%` }}
          />
        ))}
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Tasks reading "${TYPED.input}" as ${formatDue(TYPED.due!, TYPED.allDay)} in the ${TYPED.project} project, saving the open page for tomorrow, then ticking off "${BANK.title}" in Today`}
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url={PAGE.url} panelWidth={PANEL} panel={<Panel />}>
        <Page />
      </BrowserChrome>
    </DemoStage>
  )
}
